package studio.zerotohand.design;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.webkit.*;import android.util.Base64;import android.widget.Toast;import java.io.*;import java.util.*;
public class MainActivity extends Activity {
 private WebView web;private ValueCallback<Uri[]> chooser;private byte[] pending;private static final int OPEN=41,SAVE=42;
 @Override public void onCreate(Bundle state){super.onCreate(state);web=new WebView(this);setContentView(web);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setAllowFileAccessFromFileURLs(false);s.setAllowUniversalAccessFromFileURLs(false);s.setMediaPlaybackRequiresUserGesture(true);s.setSupportZoom(false);
 web.setWebViewClient(new WebViewClient(){
 @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !isLocal(r.getUrl());}
 @Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){Uri u=r.getUrl();if(!isLocal(u))return new WebResourceResponse("text/plain","UTF-8",403,"Blocked",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));String p=u.getPath().replaceFirst("^/","");if(p.isEmpty())p="index.html";if(p.contains(".."))return null;try{String mime=p.endsWith(".mjs")||p.endsWith(".js")?"text/javascript":p.endsWith(".css")?"text/css":p.endsWith(".png")?"image/png":p.endsWith(".jpg")?"image/jpeg":p.endsWith(".woff2")?"font/woff2":p.endsWith(".ttf")?"font/ttf":p.endsWith(".webmanifest")?"application/manifest+json":"text/html";return new WebResourceResponse(mime,"UTF-8",getAssets().open(p));}catch(IOException e){return new WebResourceResponse("text/plain","UTF-8",404,"Not Found",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}}
 });
 web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams params){if(chooser!=null)chooser.onReceiveValue(null);chooser=cb;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,params.getMode()==FileChooserParams.MODE_OPEN_MULTIPLE);startActivityForResult(i,OPEN);return true;}});
 web.addJavascriptInterface(new SaveBridge(),"ZTHAndroid");web.loadUrl("https://zth.local/index.html");
 }
 private boolean isLocal(Uri u){return "https".equals(u.getScheme())&&"zth.local".equals(u.getHost());}
 class SaveBridge {@JavascriptInterface public void save(String name,String encoded){if(encoded.length()>100000000)return;try{final byte[] bytes=Base64.decode(encoded,Base64.DEFAULT);final String safe=name.replaceAll("[\\\\/:*?\"<>|]","-");if(!safe.matches(".*\\.(zthpmsj|png|jpg|svg|pdf)$"))return;runOnUiThread(()->{pending=bytes;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(safe.endsWith(".png")?"image/png":safe.endsWith(".jpg")?"image/jpeg":safe.endsWith(".svg")?"image/svg+xml":"application/octet-stream");i.putExtra(Intent.EXTRA_TITLE,safe);startActivityForResult(i,SAVE);});}catch(Exception e){runOnUiThread(()->Toast.makeText(MainActivity.this,"文件过大，无法保存",Toast.LENGTH_LONG).show());}}}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==OPEN&&chooser!=null){if(result!=RESULT_OK||data==null)chooser.onReceiveValue(null);else if(data.getClipData()!=null){Uri[] arr=new Uri[data.getClipData().getItemCount()];for(int i=0;i<arr.length;i++)arr[i]=data.getClipData().getItemAt(i).getUri();chooser.onReceiveValue(arr);}else chooser.onReceiveValue(new Uri[]{data.getData()});chooser=null;}else if(req==SAVE){byte[] b=pending;pending=null;if(result==RESULT_OK&&data!=null&&b!=null)new Thread(()->{boolean ok=false;try(OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(b);ok=true;}catch(IOException e){}final boolean done=ok;runOnUiThread(()->web.evaluateJavascript("window.ZTHAndroidSaved&&window.ZTHAndroidSaved("+done+")",null));}).start();else web.evaluateJavascript("window.ZTHAndroidSaved&&window.ZTHAndroidSaved(false)",null);}}
 @Override public void onBackPressed(){web.evaluateJavascript("document.querySelector('dialog[open]')?document.querySelector('dialog[open]').close():document.body.classList.remove('show-library','show-properties')",null);}
 @Override protected void onDestroy(){if(web!=null){web.removeJavascriptInterface("ZTHAndroid");web.destroy();}super.onDestroy();}
}
